import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.dao.TransientDataAccessException;
import org.springframework.kafka.core.KafkaOperations;
import org.springframework.kafka.listener.CommonErrorHandler;
import org.springframework.kafka.listener.DeadLetterPublishingRecoverer;
import org.springframework.kafka.listener.DefaultErrorHandler;
import org.springframework.util.backoff.ExponentialBackOffWithMaxRetries;
import tools.jackson.core.JacksonException;

// Error handling for every @KafkaListener in this service. Spring Boot wires
// this bean into the auto-configured listener container factory.
//
// A failing record is retried in place with a backoff, unless the failure can
// never go away. Once it is given up on, the record is published unchanged to
// "<topic>.DLT" and the consumer moves on to the next record.
@Configuration
public class KafkaErrorHandlingConfig {

    // 4 attempts in total: the first one, then 3 retries 200 ms, 400 ms and
    // 800 ms later. The whole sequence takes about 1.4 s.
    static final int MAX_RETRIES = 3;
    static final long INITIAL_INTERVAL_MS = 200;
    static final double MULTIPLIER = 2.0;

    @Bean
    public CommonErrorHandler kafkaErrorHandler(KafkaOperations<String, String> kafka) {
        ExponentialBackOffWithMaxRetries backOff =
                new ExponentialBackOffWithMaxRetries(MAX_RETRIES);
        backOff.setInitialInterval(INITIAL_INTERVAL_MS);
        backOff.setMultiplier(MULTIPLIER);

        DefaultErrorHandler handler =
                new DefaultErrorHandler(new DeadLetterPublishingRecoverer(kafka), backOff);
        // Only retry what can succeed later. Everything else, and anything that
        // is still failing after the last attempt, goes to the dead letter topic.
