import org.apache.kafka.common.TopicPartition;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.kafka.core.KafkaOperations;
import org.springframework.kafka.listener.CommonErrorHandler;
import org.springframework.kafka.listener.DeadLetterPublishingRecoverer;
import org.springframework.kafka.listener.DefaultErrorHandler;
import org.springframework.util.backoff.ExponentialBackOff;
import tools.jackson.core.JacksonException;

// Error handling for every @KafkaListener in this service. Spring Boot wires
// this bean into the auto-configured listener container factory.
//
// A failing record is retried in place with a backoff, unless the failure can
// never go away. Once it is given up on, the record is published unchanged to
// "<topic>.DLT" and the consumer moves on to the next record.
@Configuration
public class KafkaErrorHandlingConfig {

    // 4 attempts in total: the first one, then 3 retries 200 ms, 400 ms and
    // 800 ms later. The whole sequence takes about 1.4 s.
    static final int MAX_RETRIES = 3;
    static final long INITIAL_INTERVAL_MS = 200;
    static final double MULTIPLIER = 2.0;

    static final String DLT_SUFFIX = ".DLT";

    @Bean
    public CommonErrorHandler kafkaErrorHandler(KafkaOperations<String, String> kafka) {
        ExponentialBackOff backOff = new ExponentialBackOff(INITIAL_INTERVAL_MS, MULTIPLIER);
        backOff.setMaxAttempts(MAX_RETRIES);

        // Spring Kafka's default dead letter topic is "<topic>-dlt"; ours is
        // "<topic>.DLT", on the same partition as the original record.
        DeadLetterPublishingRecoverer deadLetters = new DeadLetterPublishingRecoverer(kafka,
                (record, ex) -> new TopicPartition(record.topic() + DLT_SUFFIX, record.partition()));

        DefaultErrorHandler handler = new DefaultErrorHandler(deadLetters, backOff);
        // Failures such as TransientDataAccessException are retried by default.
        // These two can never succeed, so they go straight to the dead letter
        // topic, as does anything still failing after the last attempt.
        handler.addNotRetryableExceptions(
                JacksonException.class,       // not valid JSON for the event
                OrderNotFoundException.class); // the order will never appear
        return handler;
    }
}
